+    private sealed class LoopbackHttpServer : IDisposable
+    {
+        private readonly TcpListener _listener;
+        private readonly HttpStatusCode _statusCode;
+        private readonly string _responseBody;
+
+        public LoopbackHttpServer(HttpStatusCode statusCode, string responseBody)
+        {
+            _statusCode = statusCode;
+            _responseBody = responseBody;
+            _listener = new TcpListener(IPAddress.Loopback, 0);
+            _listener.Start();
+            Url = $"http://127.0.0.1:{((IPEndPoint)_listener.LocalEndpoint).Port}";
+            Request = HandleOneRequestAsync();
+        }
+
+        public string Url { get; }
+
+        public Task<LoopbackRequest> Request { get; }
+
+        public void Dispose()
+        {
+            _listener.Stop();
+        }
+
+        private async Task<LoopbackRequest> HandleOneRequestAsync()
+        {
+            using var client = await _listener.AcceptTcpClientAsync();
+            await using var stream = client.GetStream();
+            using var reader = new StreamReader(stream, Encoding.ASCII, leaveOpen: true);
+
+            var requestLine = await reader.ReadLineAsync() ?? "";
+            var parts = requestLine.Split(' ', 3);
+            var method = parts.Length > 0 ? parts[0] : "";
+            var pathAndQuery = parts.Length > 1 ? parts[1] : "";
+            var headers = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
+
+            string? line;
+            while (!string.IsNullOrEmpty(line = await reader.ReadLineAsync()))
+            {
+                var separator = line.IndexOf(':', StringComparison.Ordinal);
+                if (separator < 0)
+                {
+                    continue;
+                }
+
+                headers[line[..separator]] = line[(separator + 1)..].Trim();
+            }
+
+            var contentLength = headers.TryGetValue("Content-Length", out var value) &&
+                int.TryParse(value, out var parsed)
+                    ? parsed
+                    : 0;
+            var bodyChars = new char[contentLength];
+            var offset = 0;
+            while (offset < bodyChars.Length)
+            {
+                var read = await reader.ReadAsync(bodyChars.AsMemory(offset, bodyChars.Length - offset));
+                if (read == 0)
+                {
+                    break;
+                }
+
+                offset += read;
+            }
+
+            var responseBody = Encoding.UTF8.GetBytes(_responseBody);
+            var responseHeaders = Encoding.ASCII.GetBytes(
+                $"HTTP/1.1 {(int)_statusCode} {_statusCode}\r\n" +
+                "Content-Type: application/json\r\n" +
+                $"Content-Length: {responseBody.Length}\r\n" +
+                "Connection: close\r\n" +
+                "\r\n");
+            await stream.WriteAsync(responseHeaders);
+            await stream.WriteAsync(responseBody);
+
+            return new LoopbackRequest(method, pathAndQuery, headers, new string(bodyChars, 0, offset));
+        }
+    }
+
+    private sealed record LoopbackRequest(
+        string Method,
+        string PathAndQuery,
+        IReadOnlyDictionary<string, string> Headers,
+        string Body);
+
+    private sealed class RecordingHandler(Func<HttpRequestMessage, string?, HttpResponseMessage> respond)
+        : HttpMessageHandler
+    {
+        public List<RecordedRequest> Requests { get; } = [];
+
+        protected override async Task<HttpResponseMessage> SendAsync(
+            HttpRequestMessage request,
+            CancellationToken cancellationToken)
+        {
+            var body = request.Content is null
+                ? null
+                : await request.Content.ReadAsStringAsync(cancellationToken);
+
+            Requests.Add(new RecordedRequest(
+                request.Method.Method,
+                request.RequestUri?.PathAndQuery ?? "",
+                body,
+                request.Content?.Headers.ContentType?.MediaType));
+
+            return respond(request, body);
+        }
+    }
+
+    private sealed record RecordedRequest(
+        string Method,
+        string PathAndQuery,
+        string? Body,
+        string? ContentType);
+}

